import React, { useState, useEffect } from 'react';

export default function UserProfileCard({ token, setMsg }) {
  const [userSummary, setUserSummary] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!token) {
      setLoading(false);
      return;
    }

    (async () => {
      try {
        const API = process.env.REACT_APP_API || 'http://localhost:4000';
        const res = await fetch(`${API}/api/dashboard/user-summary`, {
          headers: { Authorization: `Bearer ${token}` }
        });

        if (!res.ok) throw new Error('Failed to fetch user summary');
        const data = await res.json();
        setUserSummary(data);
      } catch (err) {
        console.error(err);
        setMsg?.(err.message);
      } finally {
        setLoading(false);
      }
    })();
  }, [token, setMsg]);

  if (loading || !userSummary) {
    return (
      <div style={{
        background: '#fff',
        padding: 14,
        borderRadius: 10,
        boxShadow: '0 6px 20px rgba(2,6,23,0.04)',
        marginBottom: 14
      }}>
        <p style={{ textAlign: 'center', color: '#999' }}>Loading profile...</p>
      </div>
    );
  }

  const { user = {}, stats = {} } = userSummary;
  const role = user.role || 'Unknown';
  
  // Color code by role
  const roleColors = {
    'Admin': { bg: '#fee2e2', text: '#991b1b', icon: '🔐' },
    'NGO': { bg: '#dbeafe', text: '#1e40af', icon: '🏢' },
    'volunteer': { bg: '#dcfce7', text: '#15803d', icon: '🤝' },
    'donor': { bg: '#fef3c7', text: '#92400e', icon: '💝' }
  };

  const roleInfo = roleColors[role] || roleColors['volunteer'];

  return (
    <div style={{
      background: '#fff',
      padding: 14,
      borderRadius: 10,
      boxShadow: '0 6px 20px rgba(2,6,23,0.04)',
      marginBottom: 14
    }}>
      {/* Header: Icon + Name + Email + Role */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 12 }}>
        {/* User Icon */}
        <div style={{
          width: 50,
          height: 50,
          borderRadius: '50%',
          background: roleInfo.bg,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: 24,
          fontWeight: 'bold',
          color: roleInfo.text,
          flexShrink: 0
        }}>
          {roleInfo.icon}
        </div>

        {/* Name + Email + Role Badge */}
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 600, fontSize: 15, color: '#1f2937' }}>
            {user.name || 'Unknown'}
          </div>
          <div style={{ fontSize: 12, color: '#6b7280', marginTop: 2 }}>
            {user.email || 'No email'}
          </div>
          <div style={{
            display: 'inline-block',
            background: roleInfo.bg,
            color: roleInfo.text,
            padding: '2px 8px',
            borderRadius: 12,
            fontSize: 11,
            fontWeight: 600,
            marginTop: 4
          }}>
            {role}
          </div>
        </div>
      </div>

      {/* Points Card */}
      {user.points !== undefined && (
        <div style={{
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
          padding: 12,
          borderRadius: 8,
          color: '#fff',
          marginBottom: 12,
          textAlign: 'center'
        }}>
          <div style={{ fontSize: 24, fontWeight: 'bold' }}>
            {user.points}
          </div>
          <div style={{ fontSize: 12, opacity: 0.9, marginTop: 2 }}>
            Total Points
          </div>
        </div>
      )}

      {/* Role-Specific Stats Grid */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: role === 'Admin' ? '1fr 1fr 1fr' : '1fr 1fr',
        gap: 8
      }}>
        {role === 'Admin' && (
          <>
            <div style={{
              background: '#f3f4f6',
              padding: 10,
              borderRadius: 6,
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 18, fontWeight: 'bold', color: '#1f2937' }}>
                {stats.totalUsers || 0}
              </div>
              <div style={{ fontSize: 11, color: '#6b7280', marginTop: 2 }}>
                Total Users
              </div>
            </div>
            <div style={{
              background: '#f3f4f6',
              padding: 10,
              borderRadius: 6,
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 18, fontWeight: 'bold', color: '#1f2937' }}>
                {stats.totalEvents || 0}
              </div>
              <div style={{ fontSize: 11, color: '#6b7280', marginTop: 2 }}>
                Total Events
              </div>
            </div>
            <div style={{
              background: '#f3f4f6',
              padding: 10,
              borderRadius: 6,
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 18, fontWeight: 'bold', color: '#1f2937' }}>
                {stats.totalVolunteers || 0}
              </div>
              <div style={{ fontSize: 11, color: '#6b7280', marginTop: 2 }}>
                Volunteers
              </div>
            </div>
          </>
        )}

        {role === 'NGO' && (
          <>
            <div style={{
              background: '#f3f4f6',
              padding: 10,
              borderRadius: 6,
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 18, fontWeight: 'bold', color: '#1f2937' }}>
                {stats.eventsHosted || 0}
              </div>
              <div style={{ fontSize: 11, color: '#6b7280', marginTop: 2 }}>
                Events Hosted
              </div>
            </div>
            <div style={{
              background: '#f3f4f6',
              padding: 10,
              borderRadius: 6,
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 18, fontWeight: 'bold', color: '#1f2937' }}>
                {stats.volunteerCount || 0}
              </div>
              <div style={{ fontSize: 11, color: '#6b7280', marginTop: 2 }}>
                Volunteers
              </div>
            </div>
            <div style={{
              background: '#f3f4f6',
              padding: 10,
              borderRadius: 6,
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 18, fontWeight: 'bold', color: '#1f2937' }}>
                ₹{stats.totalDonated || 0}
              </div>
              <div style={{ fontSize: 11, color: '#6b7280', marginTop: 2 }}>
                Donations
              </div>
            </div>
          </>
        )}

        {(role === 'volunteer' || role === 'donor') && (
          <>
            <div style={{
              background: '#f3f4f6',
              padding: 10,
              borderRadius: 6,
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 18, fontWeight: 'bold', color: '#1f2937' }}>
                {stats.totalParticipation || 0}
              </div>
              <div style={{ fontSize: 11, color: '#6b7280', marginTop: 2 }}>
                Total Participation
              </div>
            </div>
            <div style={{
              background: '#f3f4f6',
              padding: 10,
              borderRadius: 6,
              textAlign: 'center'
            }}>
              <div style={{ fontSize: 18, fontWeight: 'bold', color: '#1f2937' }}>
                ₹{stats.totalDonated || 0}
              </div>
              <div style={{ fontSize: 11, color: '#6b7280', marginTop: 2 }}>
                Donated
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
